my $end = "\x03";
my $pagesep = "\x1c";
my $sep = "\x1d";
my $shortlinesep = "\x1e";
my $reallyshortlinesep = "\x1f";
# my $pag = "\e[30;102m=\e[m";

# print "\e[2 k";

my $i; my $s; my $l;
my $last = '';
while (<>) {
    chomp $last;
    $last =~ s/^ *//;
    if (/D<١>/) {
        $i = 0;
        ++$s;
        print $last, $end, "\n" if $last;
    }
    else {
        if ($last =~ /D<١>/) {
            # print $s == 1 ? "\x06" : $s == 2 ? "\x05" : ""
            print $s == 1 ? "\x06" : $s == 2 ? "\x05" : "\x04"
        }
        print $last, "\n";
    }

    my $aya = '';
    if (/^#/) {
        $l+=3;
    }

    s/\xA0(A<\N{ARABIC END OF AYAH}>D<[٠-٩]+>)\xA0(\N{ARABIC PLACE OF SAJDAH})/ $2 $1/g;
    my @w = split /\x20|(?<=\N{ARABIC START OF RUB EL HIZB})\xA0|\xA0(?=A<)/;
    for my $w (@w) { ++$i;
        if (exists $split_at[$s-1]{$i-1}) {
            ++$l;
            #
            my $S = $sep;  # $end."\x04";
            $S = $shortlinesep  # $end."\x05"
                if $l < 15
                || $s == 114 && $i > 17
                || $s == 113 && $i > 17
                || $s == 110 && $i > 17
                || $s == 108 && $i >  7
                || $s == 106 && $i > 14
                || $s == 101 && $i > 36
                ;
            $S = $reallyshortlinesep  # $end."\x06"
                if $l == 6
                || $s == 114 && $i > 19
                ;
            #
            $aya .= $S . $w;
        }
        else {
            $aya .= ' ' . $w;
        }
    }

    # $last = ($aya =~ s/[A-Z]<//gr =~ s/>//gr)."\n";
    $last = $aya;
}
say $last, $end;
# print "\e[0 k";

# LEGACY CODE {{{

sub split_lines {
    my ($sura_num, $ayat) = @_;
    my $word = 0;
    my $line = 0;
    my $startline;

    my @sp = @{$split_at[$sura_num-1]};
    # return $ayat =~ s/\n+/ /gr unless scalar @sp;

    local *_split = sub {
        ++$word;
        my $c = grep { $_ == $word } @sp;
        if ($c == 0) { return "+" }  # no line break
        if ($c == 1) {
            ++$line;
            if ($startline) {
                if    (($line - $startline) % 30 == 0) { # outer page break
                    return "\n\n\n"
                }
                elsif (($line - $startline) % 15 == 0) { # inner page break
                    return "\n\n"
                }
            }
            return "\n"  # in-page line break
        }
        if ($c == 2) {  # inner page break
            ++$line;
            $startline = $line + 15;
            return "\n\n"
        }
        if ($c == 3) {  # outer page break
            ++$line;
            $startline = $line;
            return "\n\n\n"
        }
        die "LINE SPLIT ERROR!\n";
    };

    # preprocessing:
    # - split before ayah numbers, too.
    $ayat =~ s/\N{NBSP}(?!\N{ARABIC LETTER SUPERSCRIPT ALEF})/ /g;
    # - swap ayah number and place of sajdah
    $ayat =~ s/ ( A<\N{ARABIC END OF AYAH}> D<[٠-٩]+>
                |   \N{ARABIC END OF AYAH}    [٠-٩]+
                )
                [ ]
                (\N{ARABIC PLACE OF SAJDAH})
              /$2 $1/gx;
    # - conventionally, rub el hizb sign is not put when it's at the sura beginning
    $ayat =~ s/\A\N{ARABIC START OF RUB EL HIZB} //;

    # the actual splitting
    $ayat =~ s/[ \n]+(?=.)/_split()/ge;

    # post-processing
    $ayat =~ s/[ +\n]+\Z//;  # remove trailing spaces/newlines

    return $ayat;
}

# }}}
